import{_ as o,o as l,c as e,a5 as r}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"快速了解","description":"Blob（Binary Large Object）是 Web 编程中用于表示原始数据的对象，通常用于处理图片、视频、音频等文件类型的数据。 一、 Blob 是什么？ Blob 是一个二进制数据的集合。它可以表示任意的原始数据，不限于特定格式。Blob 的主要特点是： 不可变 ：一。","frontmatter":{"title":"快速了解","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"Blob（Binary Large Object）是 Web 编程中用于表示原始数据的对象，通常用于处理图片、视频、音频等文件类型的数据。 一、 Blob 是什么？ Blob 是一个二进制数据的集合。它可以表示任意的原始数据，不限于特定格式。Blob 的主要特点是： 不可变 ：一。","sidebarWeight":80,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/blob/快速了解/快速了解.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/快速了解.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/快速了解.md"}'),n={name:"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/快速了解.md"};function a(s,t,i,b,g,u){return l(),e("div",null,[...t[0]||(t[0]=[r('<div><h1 id="快速了解" tabindex="-1">快速了解 <a class="header-anchor" href="#快速了解" aria-label="Permalink to &quot;快速了解&quot;">​</a></h1><blockquote><p>本节目标：理解“快速了解”的核心思路，并能把它用于实际开发或面试表达。 Blob（Binary Large Object）是 Web 编程中用于表示原始数据的对象，通常用于处理图片、视频、音频等文件类型的数据。 **一、**<strong>Blob</strong> <strong>是什么？</strong> Blob 是一个二进制数据的集合。它可以表示任意的原始数据，不限于特定格式。Blob 的主要特点是：</p></blockquote><ul><li><strong>不可变</strong>：一旦创建，Blob 的内容无法修改，只能通过操作新数据来创建新的 Blob。</li><li><strong>数据块</strong>：可以是文本、图片、视频、音频等任意数据的二进制表示。</li><li><strong>内存高效</strong>：Blob 可以存储大量数据，适合用于文件下载、上传和数据传输。</li></ul><p>**二、**<strong>Blob</strong> <strong>的主要属性和方法</strong><strong>1. 创建</strong> <strong>Blob</strong> 使用 Blob 构造函数创建一个 Blob 对象： const blob = new Blob([data], { type: &quot;mime-type&quot; });</p><ul><li><strong>data</strong>：一个数组，包含需要存储的数据，可以是字符串、ArrayBuffer、TypedArray 或其他 Blob。</li><li><strong>type</strong>：MIME 类型，用于指示数据类型，例如 image/png、text/plain、application/pdf 等。 <ul><li><strong>是否需要指定 MIME 类型？</strong><ul><li><strong>推荐指定</strong>：指定 MIME 类型（例如 &quot;application/vnd.ms-word&quot;）能够帮助浏览器和操作系统更好地理解文件内容，并且在文件下载和打开时采用正确的程序。</li><li><strong>不指定也能正常运行</strong>：即使不指定 MIME 类型，文件仍然可以下载，但有时会缺乏文件类型信息（例如，可能不能自动选择正确的应用程序打开文件）。</li></ul></li><li>因此，指定 MIME 类型是一个最佳实践，它可以提升文件的兼容性和可用性。</li></ul></li></ul><p><strong>示例：</strong> const textBlob = new Blob([&quot;Hello, world!&quot;], { type: &quot;text/plain&quot; });</p><p><strong>2. 主要属性</strong></p><ul><li><strong>size</strong>：Blob 的大小（字节），例如 blob.size。</li><li><strong>type</strong>：MIME 类型，例如 blob.type。</li></ul><p><strong>示例：</strong> console.log(textBlob.size); // 输出 Blob 的字节大小 console.log(textBlob.type); // 输出 &quot;text/plain&quot;</p><p><strong>3. 主要方法</strong></p><ul><li><strong>Blob.slice([start[, end[, contentType]]])</strong>：从 Blob 中提取一个新 Blob。可以指定起始和结束的字节位置以及新 Blob 的类型。</li></ul><p>const slice = textBlob.slice(0, 5); // 提取前5个字节</p><ul><li><strong>URL.createObjectURL(blob)</strong>：生成一个指向 Blob 的临时 URL，用于直接引用 Blob 数据。const url = URL.createObjectURL(textBlob);</li></ul><p>URL.createObjectURL(blob) 确实创建了一个指向 Blob 的引用。返回的 url 是一个基于 blob: 协议的 URL，通常格式为 blob:&lt;origin&gt;/&lt;unique-identifier&gt;。 这个 URL 只在当前页面的会话中有效，可以在 HTML 元素（例如 &lt;a&gt; 标签的 href）中使用，并允许浏览器在需要时访问和使用该 Blob 数据。</p><ul><li><strong>URL.revokeObjectURL(url)</strong>：释放临时 URL 占用的资源。URL.revokeObjectURL(url);</li><li><strong>Blob.text()</strong>：返回 Blob 内容的 Promise，用于读取文本数据。textBlob.text().then((text) =&gt;console.log(text)); // 输出 &quot;Hello, world!&quot;</li><li><strong>Blob.arrayBuffer()</strong>：返回一个包含 Blob 内容的 ArrayBuffer 的 Promise，用于读取二进制数据。textBlob.arrayBuffer().then((buffer) =&gt;console.log(buffer));</li></ul><p>**三、**<strong>Blob</strong> <strong>的实际应用场合</strong></p><ol><li><strong>文件下载</strong>：Blob 常用于下载功能，特别是在需要从网络获取文件、处理数据然后下载时。</li></ol><p>const blob = new Blob([&quot;Hello, world!&quot;], { type: &quot;text/plain&quot; }); const url = URL.createObjectURL(blob); const a = document.createElement(&quot;a&quot;); a.href = url; a.download = &quot;example.txt&quot;; a.click(); URL.revokeObjectURL(url); // 释放资源</p><ol start="3"><li><strong>文件上传</strong>：Blob 可用于存储并上传用户选择的文件，通过 FormData 对象与后端交互。</li></ol><p>const formData = new FormData(); formData.append(&quot;file&quot;, blob, &quot;example.txt&quot;); fetch(&quot;/upload&quot;, { method: &quot;POST&quot;, body: formData });</p><ol start="5"><li>图片处理：Blob 可用于处理图片文件，比如将 &lt;canvas&gt; 中的图像转换为 Blob 并保存。</li></ol><p>canvas.toBlob((blob) =&gt; { const url = URL.createObjectURL(blob); const img = document.createElement(&quot;img&quot;); img.src = url; document.body.appendChild(img); URL.revokeObjectURL(url); });</p><ol start="7"><li>显示媒体数据：Blob 常用于生成临时 URL，方便在网页上直接预览文件内容，例如预览音频、视频、图片等数据。</li></ol><p>**四、**<strong>Blob</strong> <strong>在开发中的其他重要知识</strong></p><ol><li><strong>MIME 类型</strong>：指定正确的 MIME 类型非常重要，尤其在下载和显示数据时。常见类型包括： <ul><li>文本：text/plain，text/html</li><li>图片：image/png，image/jpeg</li><li>文档：application/pdf，application/vnd.ms-excel</li></ul></li><li><strong>内存管理</strong>：Blob 数据占用较多内存，使用 URL.revokeObjectURL() 及时释放临时 URL，可以避免内存泄漏。</li><li><strong>文件处理能力有限</strong>：Blob 主要用于客户端，通常只适合小文件处理，如果文件非常大（如视频文件），建议在后端进行处理。</li><li><strong>安全限制</strong>：Blob URL 在生成后是与 origin 绑定的，跨域访问被限制，适合在客户端内部传递和处理数据。</li><li><strong>异步读取</strong>：Blob.text() 和 Blob.arrayBuffer() 提供异步读取功能，更适合现代开发需求。</li></ol><p><strong>示例总结</strong> 以下是一个综合示例，演示了 Blob 的生成、下载和资源释放： const exportData = async (data) =&gt; { // 创建 Blob const blob = new Blob([data], { type: &quot;application/json&quot; }); // 创建临时 URL const url = URL.createObjectURL(blob); // 创建下载链接 const a = document.createElement(&quot;a&quot;); a.href = url; a.download = &quot;data.json&quot;; document.body.appendChild(a); a.click(); // 释放 URL URL.revokeObjectURL(url); }; // 使用示例 const jsonData = JSON.stringify({ name: &quot;Alice&quot;, age: 30 }); exportData(jsonData); Blob 是处理文件数据、实现下载和数据传递的实用工具。通过 Blob 的灵活操作，可以大幅提升 Web 应用的用户体验，例如支持用户在客户端直接预览、下载文件等。</p></div>',1)])])}const B=o(n,[["render",a]]);export{p as __pageData,B as default};
